'use strict';

// MODULES //

var copy = require( '@stdlib/utils/copy' );
var isObject = require( '@stdlib/assert/is-object' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var findJSDoc = require( '@stdlib/_tools/eslint/utils/find-jsdoc' );
var DEFAULTS = require( './defaults.json' );


// VARIABLES //

var rule;
var RE_PARAM = /\*(\s*)@param(\s*)\{[^}]*\}(\s*)(\[[^\]]+\]|[a-zA-Z0-9_$.]+)(.*)$/;
var RE_AFTER_PARAM = /^(\s*)([-–—−]|--|:)?(\s*)(\S.*)?$/;


// FUNCTIONS //

/**
* Rule for validating hyphen spacing in JSDoc `@param` tags.
*
* @param {Object} context - ESLint context
* @returns {Object} validators
*/
function main( context ) {
	var options;
	var source;
	var opts;

	opts = copy( DEFAULTS );
	options = context.options[ 0 ];
	if ( isObject( options ) ) {
		if ( hasOwnProp( options, 'before' ) ) {
			opts.before = options.before;
		}
		if ( hasOwnProp( options, 'after' ) ) {
			opts.after = options.after;
		}
	}
	source = context.sourceCode;

	return {
		'FunctionExpression:exit': validate,
		'FunctionDeclaration:exit': validate,
		'VariableDeclaration:exit': validate,
		'ExpressionStatement:exit': validate
	};

	/**
	* Checks whether JSDoc `@param` tags adhere to hyphen spacing rules.
	*
	* @private
	* @param {ASTNode} node - AST node
	*/
	function validate( node ) {
		var lines;
		var jsdoc;
		var i;

		jsdoc = findJSDoc( source, node );
		if ( isObject( jsdoc ) ) {
			lines = jsdoc.value.split( '\n' );
			for ( i = 0; i < lines.length; i++ ) {
				validateLine( lines[ i ], jsdoc, i );
			}
		}
	}

	/**
	* Validates hyphen spacing for a single JSDoc line.
	*
	* @private
	* @param {string} line - comment line
	* @param {Object} jsdoc - JSDoc comment object
	* @param {number} idx - line index
	*/
	function validateLine( line, jsdoc, idx ) {
		var lineNumber;
		var matches;
		var match;
		var loc;

		matches = line.match( RE_PARAM );
		if ( !matches ) {
			return;
		}
		lineNumber = jsdoc.loc.start.line + idx;
		loc = {
			'start': {
				'line': lineNumber,
				'column': 0
			},
			'end': {
				'line': lineNumber,
				'column': line.length
			}
		};
		match = matches[ 5 ].match( RE_AFTER_PARAM );
		if ( match ) {
			validateHyphenSpacing( match, loc );
		}
	}

	/**
	* Validates the separator and spacing around a hyphen in a `@param` tag.
	*
	* @private
	* @param {Array<string>} match - regex match results
	* @param {Object} loc - line location
	*/
	function validateHyphenSpacing( match, loc ) {
		if ( !match[ 2 ] && match[ 4 ] ) {
			report( 'parameter name and description should be separated by a hyphen', loc );
			return;
		}
		if ( !match[ 2 ] ) {
			return;
		}
		if ( match[ 2 ] !== '-' ) {
			report( 'parameter name and description should be separated by a hyphen', loc );
		}
		validateBeforeSpacing( match, loc );
		validateAfterSpacing( match, loc );
	}

	/**
	* Validates spacing before a hyphen in a `@param` tag.
	*
	* @private
	* @param {Array<string>} match - regex match results
	* @param {Object} loc - line location
	*/
	function validateBeforeSpacing( match, loc ) {
		if ( opts.before ) {
			if ( match[ 1 ].length < 1 ) {
				report( 'hyphen should be preceded by a space', loc );
			} else if ( match[ 1 ].length > 1 ) {
				report( 'hyphen should be preceded by only one space', loc );
			}
		} else if ( match[ 1 ].length > 0 ) {
			report( 'there should be no space before hyphen', loc );
		}
	}

	/**
	* Validates spacing after a hyphen in a `@param` tag.
	*
	* @private
	* @param {Array<string>} match - regex match results
	* @param {Object} loc - line location
	*/
	function validateAfterSpacing( match, loc ) {
		if ( !match[ 4 ] ) {
			return;
		}
		if ( opts.after ) {
			if ( match[ 3 ].length < 1 ) {
				report( 'hyphen should be followed by a space', loc );
			} else if ( match[ 3 ].length > 1 ) {
				report( 'hyphen should be followed by only one space', loc );
			}
		} else if ( match[ 3 ].length > 0 ) {
			report( 'there should be no space after hyphen', loc );
		}
	}

	/**
	* Reports the error message.
	*
	* @private
	* @param {string} msg - error message
	* @param {Object} loc - lines of code (object with `start` and `end` properties)
	*/
	function report( msg, loc ) {
		context.report({
			'node': null,
			'message': msg,
			'loc': loc
		});
	}
}


// MAIN //

rule = {
	'meta': {
		'docs': {
			'description': 'enforce hyphen spacing in JSDoc @param tags'
		},
		'schema': [
			{
				'type': 'object',
				'properties': {
					'before': {
						'type': 'boolean'
					},
					'after': {
						'type': 'boolean'
					}
				},
				'additionalProperties': false
			}
		]
	},
	'create': main
};


// EXPORTS //

module.exports = rule;
